# SD04 clean viewer helper in cockpit and public Room.
for path in ["components/sd04-offer-builder.tsx", "components/public-sd-room-v6.tsx"]:
    p = ROOT / path; text = p.read_text()
    if 'const cleanPdfViewerUrl' not in text:
        anchor = 'const isPdfUrl = (value: string) => /^https?:\\/\\//i.test(value || "");\n' if path.endswith('sd04-offer-builder.tsx') else 'const OPTIONAL_CODES: SDCode[] = ["SD03", "SD04"];\n'
        if anchor not in text: raise RuntimeError(f"PDF helper anchor missing {path}")
