text = text.replace('<div className="ml-auto hidden items-center gap-2 text-[12px] text-[#737c81] sm:flex"><LockKeyhole className="h-3.5 w-3.5" /> Room privée</div>', '<div className="ml-auto flex items-center gap-2"><Languages className="h-3.5 w-3.5 text-[#737c81]" /><div className="inline-flex rounded-lg border border-[#dfe3e5] bg-[#f7f8f8] p-0.5 text-[11px] font-semibold"><button type="button" onClick={() => changeLanguage("fr")} className={`rounded-md px-2 py-1 ${language === "fr" ? "bg-white text-[#202a2f] shadow-sm" : "text-[#737c81]"}`}>FR</button><button type="button" onClick={() => changeLanguage("en")} className={`rounded-md px-2 py-1 ${language === "en" ? "bg-white text-[#202a2f] shadow-sm" : "text-[#737c81]"}`}>EN</button></div><div className="hidden items-center gap-2 text-[12px] text-[#737c81] sm:flex"><LockKeyhole className="h-3.5 w-3.5" /> {tr(language, "Room privée", "Private Room")}</div></div>')
text = text.replace('subtitle={data.room.displaySubtitle || "Espace de collaboration stratégique"}', 'subtitle={language === "en" ? "Collaboration space" : (data.room.displaySubtitle || "Espace de collaboration")}')
text = text.replace('stageTitle(code)', 'stageTitle(code, language)').replace('stageTitle(currentDocument.code)', 'stageTitle(currentDocument.code, language)')
