text = text.replace('{OPTIONAL_CODES.includes(currentDocument.code) ? " · Facultatif" : " · Obligatoire"}', '{OPTIONAL_CODES.includes(currentDocument.code) ? tr(language, " · Facultatif", " · Optional") : tr(language, " · Obligatoire", " · Required")}')
text = text.replace('{currentDocument.status === "validated" ? "Validé" : "À valider"}', '{currentDocument.status === "validated" ? tr(language, "Validé", "Approved") : tr(language, "À valider", "To approve")}')
